import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.orders.api.OrderSummary;
import com.wolinski.shop.shipping.api.CarrierGateway;
import java.time.Instant;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class OrderService implements OrderFacade {

    private final OrderRepository orders;
    private final CarrierGateway carrier;
    private final TransactionTemplate transactions;

    public OrderService(OrderRepository orders, CarrierGateway carrier, PlatformTransactionManager transactionManager) {
        this.orders = orders;
        this.carrier = carrier;
        this.transactions = new TransactionTemplate(transactionManager);
    }

    @Override
    @Transactional
    public String place(String customerId, Money total, Instant placedAt) {
        Order order = new Order(UUID.randomUUID().toString(), customerId, total, placedAt);
        orders.save(order);
        return order.id();
    }

    /**
     * Not transactional as a whole: the confirmation commits before the carrier is called (ADR 0005).
     * If the carrier fails, the order stays CONFIRMED without a tracking number, and a retry books it.
     */
    @Override
    public void confirm(String orderId) {
        boolean needsShipment = transactions.execute(status -> {
            Order order = orders.get(orderId);
            order.changeStatus("CONFIRMED");
            return order.trackingNumber() == null;
        });
        if (!needsShipment) {
            return;
        }
        String trackingNumber = carrier.book(orderId);
        transactions.executeWithoutResult(status -> orders.get(orderId).changeTrackingNumber(trackingNumber));
    }

    @Override
    @Transactional
    public void cancel(String orderId) {
        orders.get(orderId).changeStatus("CANCELLED");
    }

    @Override
    @Transactional(readOnly = true)
    public OrderSummary summary(String orderId) {
        Order order = orders.get(orderId);
        return new OrderSummary(order.id(), order.customerId(), order.total(), order.status(), order.trackingNumber());
    }
}
}

